CREATE TABLE IF NOT EXISTS games(id VARCHAR(64) PRIMARY KEY, name VARCHAR(128) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, config_version INT NOT NULL DEFAULT 1);
INSERT IGNORE INTO games(id,name) VALUES ('sky-island','天空岛物语');
CREATE TABLE IF NOT EXISTS accounts(id VARCHAR(64) PRIMARY KEY, secret_hash CHAR(64) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash CHAR(64) PRIMARY KEY, player_id VARCHAR(64) NOT NULL, expires_at BIGINT NOT NULL, INDEX(player_id));
CREATE TABLE IF NOT EXISTS profiles(game_id VARCHAR(64), player_id VARCHAR(64), name VARCHAR(64) NOT NULL DEFAULT '', data JSON NOT NULL, PRIMARY KEY(game_id,player_id));
